// Collect GitHub activity — n8n Code node (Run Once for All Items).
// Reads config from the "Config" Set node. Paginates the GitHub REST API
// (Link-header following), filters to the trailing 7-day window, dedupes.
const cfg = $('Config').first().json;
const owner = (cfg.repo_owner || '').trim();
const repo = (cfg.repo_name || '').trim();
if (!owner || !repo) throw new Error('Config: repo_owner and repo_name are required.');

const now = new Date();
const since = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
const sinceIso = since.toISOString();

const headers = {
  'Accept': 'application/vnd.github+json',
  'User-Agent': 'n8n-weekly-dev-summary'
};
if (cfg.github_token && String(cfg.github_token).trim() && !String(cfg.github_token).includes('PASTE')) {
  headers['Authorization'] = 'Bearer ' + String(cfg.github_token).trim();
}

async function getAll(path) {
  let url = 'https://api.github.com' + path + (path.includes('?') ? '&' : '?') + 'per_page=100';
  const out = [];
  let guard = 0;
  while (url) {
    if (++guard > 50) throw new Error('Pagination guard tripped (>50 pages).');
    const res = await fetch(url, { headers });
    if (!res.ok) {
      const body = await res.text().catch(() => '');
      throw new Error('GitHub API ' + res.status + ' on ' + url + ' :: ' + body.slice(0, 200));
    }
    const data = await res.json();
    out.push(...(Array.isArray(data) ? data : [data]));
    const link = res.headers.get('link') || '';
    const m = link.match(/<([^>]+)>;\s*rel="next"/);
    url = m ? m[1] : null;
  }
  return out;
}

const commitsRaw = await getAll(`/repos/${owner}/${repo}/commits?since=${sinceIso}`);
const issuesRaw = await getAll(`/repos/${owner}/${repo}/issues?state=closed&since=${sinceIso}`);
// Pulls have no server-side merged-since filter, so page with early exit:
// sorted by updated desc, and updated_at >= merged_at always, so once a full
// page is older than the window, no later page can hold a merged PR in-window.
const pullsRaw = [];
{
  let url = `https://api.github.com/repos/${owner}/${repo}/pulls?state=closed&sort=updated&direction=desc&per_page=100`;
  let guard = 0;
  while (url) {
    if (++guard > 50) throw new Error('Pulls pagination guard tripped (>50 pages).');
    const res = await fetch(url, { headers });
    if (!res.ok) throw new Error('GitHub API ' + res.status + ' on pulls');
    const page = await res.json();
    pullsRaw.push(...page);
    const fresh = page.filter(p => p.updated_at && new Date(p.updated_at) >= since);
    const link = res.headers.get('link') || '';
    const m = link.match(/<([^>]+)>;\s*rel="next"/);
    url = (fresh.length > 0 && m) ? m[1] : null;
  }
}

const commits = [];
const seenSha = new Set();
for (const c of commitsRaw) {
  if (!c.sha || seenSha.has(c.sha)) continue;
  seenSha.add(c.sha);
  const ca = c.commit && c.commit.author ? c.commit.author : {};
  commits.push({
    sha: c.sha.slice(0, 7),
    message: String((c.commit && c.commit.message) || '').split('\n')[0],
    author: ca.name || '',
    date: ca.date || ''
  });
}

const closed_issues = [];
for (const i of issuesRaw) {
  if (i.pull_request) continue; // the issues endpoint also returns PRs
  if (!i.closed_at || new Date(i.closed_at) < since) continue;
  closed_issues.push({ number: i.number, title: i.title, closed_at: i.closed_at });
}

const merged_prs = [];
for (const p of pullsRaw) {
  if (!p.merged_at || new Date(p.merged_at) < since) continue;
  merged_prs.push({
    number: p.number,
    title: p.title,
    merged_at: p.merged_at,
    author: (p.user && p.user.login) || ''
  });
}

return [{
  json: {
    repo: owner + '/' + repo,
    window: { since: since.toISOString(), until: now.toISOString() },
    commits,
    closed_issues,
    merged_prs,
    counts: {
      commits: commits.length,
      closed_issues: closed_issues.length,
      merged_prs: merged_prs.length
    }
  }
}];

// Build prompt — n8n Code node (Run Once for All Items).
// Turns the collected activity into a Claude prompt in EN or FR (per Config).
// Quiet weeks get an explicit "quiet week" brief instead of an empty summary.
const d = $input.first().json;
const cfg = $('Config').first().json;
const lang = String(cfg.language || 'EN').toUpperCase() === 'FR' ? 'FR' : 'EN';
const { commits, closed_issues, merged_prs, counts, window, repo } = d;

function section(title, items, fmt) {
  if (!items.length) return title + '\n(none this week)';
  const shown = items.slice(0, 60).map(fmt).join('\n');
  const more = items.length > 60 ? `\n...and ${items.length - 60} more` : '';
  return title + '\n' + shown + more;
}

const dataBlock =
  section('COMMITS (' + counts.commits + ')', commits,
    c => `- ${c.sha} | ${c.message} | ${c.author} | ${c.date}`) +
  '\n\n' +
  section('CLOSED ISSUES (' + counts.closed_issues + ')', closed_issues,
    i => `- #${i.number} | ${i.title} | closed ${i.closed_at}`) +
  '\n\n' +
  section('MERGED PULL REQUESTS (' + counts.merged_prs + ')', merged_prs,
    p => `- #${p.number} | ${p.title} | by ${p.author} | merged ${p.merged_at}`);

let prompt;
if (lang === 'FR') {
  prompt =
    'Tu es un rédacteur technique qui résume l’activité hebdomadaire d’un dépôt GitHub. ' +
    'Rédige un résumé narratif clair et concis en français, structuré en trois parties : « Temps forts », « Détail par catégorie », « À surveiller la semaine prochaine ». ' +
    'Ton : professionnel, factuel, sans jargon inutile. 250 mots maximum.\n\n' +
    'DÉPÔT : ' + repo + '\n' +
    'SEMAINE : ' + window.since.slice(0, 10) + ' → ' + window.until.slice(0, 10) + '\n\n' +
    'DONNÉES D’ACTIVITÉ :\n' + dataBlock +
    (counts.commits + counts.closed_issues + counts.merged_prs === 0
      ? '\n\nNote : aucune activité cette semaine. Rédige une brève note « semaine calme » en une phrase.'
      : '');
} else {
  prompt =
    'You are a technical writer summarizing one week of GitHub repository activity. ' +
    'Write a clear, concise narrative summary in English with three sections: "Highlights", "By category", "Watch next week". ' +
    'Tone: professional, factual, no fluff. 250 words max.\n\n' +
    'REPO: ' + repo + '\n' +
    'WEEK: ' + window.since.slice(0, 10) + ' → ' + window.until.slice(0, 10) + '\n\n' +
    'ACTIVITY DATA:\n' + dataBlock +
    (counts.commits + counts.closed_issues + counts.merged_prs === 0
      ? '\n\nNote: zero activity this week. Write a one-sentence "quiet week" note instead.'
      : '');
}

return [{ json: { prompt, counts, window, repo, language: lang } }];
